// Imported scalar fields use text, integer and boolean tuples.
// Unwrap those values within ordinary arrays and objects.
// Collection and structured tuples (list, set, date and object) are opaque:
// preserve the complete tuple and its nested content in stored records.
const scalarTags = new Set(['text', 'integer', 'boolean']);
function unwrapScalar(tag, value) {
  if (tag === 'text') return value;
  if (tag === 'integer') {
    const parsed = Number(value);
    return Number.isFinite(parsed) ? parsed : value;
  }
  if (tag === 'boolean') return value === true || value === 'true';
  return value;
}
function isScalar(value) {
  return Array.isArray(value) && value.length === 2 && scalarTags.has(value[0]);
}
function normalizeRecord(value) {
  if (isScalar(value)) return unwrapScalar(value[0], value[1]);
  if (Array.isArray(value)) return value.map(normalizeRecord);
  if (value === null || typeof value !== 'object') return value;
  return Object.fromEntries(Object.entries(value).map(([name, entry]) => [name, normalizeRecord(entry)]));
}
const state = $getWorkflowStaticData('global');
const records = $input.all().map(item => ({ ...item, json: normalizeRecord(item.json) }));
state.importedRecords = records.map(item => item.json);
return records;
